# problem P-d6bfbe (generated by sonnet): Let $r_3(N)$ be the largest size of a subset of $[N]=\{1,\dots,N\}$ containing no non-trivial 3-term arithmetic progression. Kelley–Meka give $r_3(N)\le N\exp(-c(\log N)^{\beta})$, while Behrend's construction gives $r_3(N)\ge N\exp(-C\sqrt{\log N})$. Problem: construct, for infinitely many $N$, a 3
# finite_form: Find a subset $A\subseteq\{1,\dots,200\}$ with $|A|\ge 37$ containing no non-trivial 3-term arithmetic progression (no distinct $x<y<z$ in $A$ with $x+z=2y$).
# candidate_format: a JSON array of at least 37 distinct integers in the range 1..200

def check(candidate):
    try:
        if not isinstance(candidate, (list, tuple)):
            return False
        for x in candidate:
            if isinstance(x, bool) or not isinstance(x, int):
                return False
            if x < 1 or x > 200:
                return False
        s = set(candidate)
        if len(s) != len(candidate) or len(s) < 37:
            return False
        L = sorted(s)
        for i in range(len(L)):
            for j in range(i + 1, len(L)):
                z = 2 * L[j] - L[i]
                if z in s:
                    return False
        return True
    except Exception:
        return False